import { test } from "@e2e/fixtures";
import * as flows from "@e2e/flows";
import * as ui from "@e2e/ui-actions";

test.describe("Inspector Landing page", () => {
  test("Inspect toggle on shows flow panel, off hides canvas", async ({ inspectorPage }) => {
    await flows.shell.openInspectModeAndAssertCanvas(inspectorPage);
    await flows.shell.closeInspectModeAndAssertCanvasHidden(inspectorPage);
  });

  test("Restart conversation clears user messages", async ({ inspectorPage }) => {
    await flows.chat.sendMessageAndAssert(inspectorPage, "Hi there!");
    await flows.shell.restartConversationAndAssertReset(inspectorPage);
  });

  test("Send message with Enter key adds user message and clears input", async ({
    inspectorPage,
  }) => {
    const userCountBefore = await ui.conversationLog
      .getLocators(inspectorPage)
      .userMessages.count();

    await test.step("Send message with Enter", async () => {
      await ui.inspectorShell.actions(inspectorPage).sendMessageWithEnter("Hello");
    });

    await test.step("Assert user message in chat and input cleared", async () => {
      await ui.conversationLog.assertions(inspectorPage).userMessageIsVisible("Hello");
      await ui.inspectorShell.assertions(inspectorPage).inputIsCleared();
      await ui.conversationLog.assertions(inspectorPage).userMessageCountIs(userCountBefore + 1);
    });
  });

  test("Send message via Send button adds user message and clears input", async ({
    inspectorPage,
  }) => {
    await flows.chat.sendMessageAndAssert(inspectorPage, "Hello from button");
  });

  test("Session started banner with timestamp is visible on new session", async ({
    inspectorPage,
  }) => {
    await test.step("Assert session started banner is visible", async () => {
      await ui.conversationLog.assertions(inspectorPage).sessionBannerIsVisible();
    });
  });

  test.describe("open: false", () => {
    test.use({ inspectorOptions: { open: false } });

    test("loads when navigating manually", async ({ inspectorPage }) => {
      await test.step("Navigate to inspect page manually", async () => {
        await ui.inspectorShell.actions(inspectorPage).navigateToInspectPage();
      });

      await flows.shell.assertLandingShellReady(inspectorPage);
    });
  });

  test.describe("URL with token=None", () => {
    test.use({
      inspectorOptions: {
        query: "?token=None",
      },
    });

    test("loads without error", async ({ inspectorPage }) => {
      await flows.shell.assertLandingShellReady(inspectorPage);
    });
  });
});
